<?php require __DIR__.'/../../layouts/header.php'; ?><div class="toolbar"><div><h1 class="page-title">Reporte general por cohorte</h1><p class="subtitle">[PROVISIONAL] El promedio de calificaciones es informativo.</p></div></div><div class="card"><div class="card-body"><form method="get" class="form-grid"><div><label>Cohorte</label><select name="id_cohorte"><option value="0">Todas</option><?php foreach($cohortes as $c): ?><option value="<?=$c['id_cohorte']?>" <?=$cohorte===$c['id_cohorte']?'selected':''?>><?=e($c['nombre'])?></option><?php endforeach;?></select></div><div><label>Modalidad</label><select name="id_modalidad"><option value="0">Todas</option><?php foreach($modalidades as $m): ?><option value="<?=$m['id_modalidad']?>" <?=$modalidad===$m['id_modalidad']?'selected':''?>><?=e($m['nombre'])?></option><?php endforeach;?></select></div><div><label>Etapa</label><select name="etapa"><option value="">Todas</option><option>previa</option><option>mg1</option><option>mg2</option><option>finalizado</option></select></div><div><label>Estado</label><select name="estado"><option value="">Todos</option><option>activo</option><option>aprobado</option><option>reprobado</option><option>abandono</option><option>retirado</option></select></div><button class="btn btn-primary">Filtrar</button><a class="btn btn-light" href="?<?=http_build_query(array_merge($_GET,['formato'=>'csv']))?>">Exportar CSV</a></form></div></div><div class="card"><div class="card-body"><div class="form-grid" style="margin-bottom:18px"><div><strong>Expedientes encontrados</strong><div style="font-size:28px;font-weight:700"><?= count($filas) ?></div></div><div><strong>Activos</strong><div style="font-size:28px;font-weight:700"><?= count(array_filter($filas, fn($r) => $r['estado'] === 'activo')) ?></div></div><div><strong>Con avance registrado</strong><div style="font-size:28px;font-weight:700"><?= count(array_filter($filas, fn($r) => $r['ultimo_avance'] !== null && $r['ultimo_avance'] !== '')) ?></div></div></div><canvas id="graficoMg" height="100"></canvas><table class="table"><tr><th>Estudiante</th><th>Modalidad</th><th>Cohorte</th><th>Etapa</th><th>Inicio</th><th>Avance</th><th>Estado</th></tr><?php if (!$filas): ?><tr><td colspan="7">No hay expedientes para los filtros seleccionados.</td></tr><?php endif; ?><?php foreach($filas as $r): ?><tr><td><?=e($r['apellido'].', '.$r['nombre'])?></td><td><?=e($r['modalidad_nombre'])?></td><td><?=e($r['cohorte_nombre'])?></td><td><?=e($r['etapa_actual'])?></td><td><?=e($r['fecha_inicio'])?></td><td><?=e($r['ultimo_avance']??'—')?></td><td><?=e($r['estado'])?></td></tr><?php endforeach;?></table></div></div><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>new Chart(document.getElementById('graficoMg'),{type:'bar',data:{labels:<?=json_encode(array_keys($resumen),JSON_UNESCAPED_UNICODE)?>,datasets:[{label:'Expedientes',data:<?=json_encode(array_values($resumen))?>}]}});</script><?php require __DIR__.'/../../layouts/footer.php'; ?>
